objectKeysSection.exampleCode:
const id = Symbol('id');
const usuario = {
  nome: 'Rodrigo',
  [id]: 1001 // Chave dinâmica calculada
};

console.log(Object.keys(usuario)); // ['nome']
console.log(usuario[id]); // 1001
console.log(JSON.stringify(usuario)); // '{"nome":"Rodrigo"}'
console.log(Object.getOwnPropertySymbols(usuario)); // [Symbol(id)]

