let regexp = /JavaScript/;

// Lança TypeError:
// 'First argument to startsWith must not be a regular expression'
'/JavaScript/'.startsWith(regexp);

let regexp = /JavaScript/;

// Desativamos a identificação de match:
regexp[Symbol.match] = false;

// Agora a execução é permitida e retorna true:
console.log('/JavaScript/'.startsWith(regexp)); // true!

