// ============================================================================
// Aula 10: Symbol & Well-Known Symbols - Rodrigo Branas
// ============================================================================

console.info('1. UNICIDADE DO TIPO PRIMITIVO SYMBOL');
const s1 = Symbol('descricao');
const s2 = Symbol('descricao');

console.log('s1:', s1);
console.log('s2:', s2);
console.log('s1 === s2:', s1 === s2); // false (garantidamente únicos!)
console.log('typeof s1:', typeof s1); // 'symbol'

console.info('\n2. CHAVE ÚNICA EM OBJETOS E ENUMERAÇÃO');
const chaveId = Symbol('id');
const usuario = {
  nome: 'Rodrigo Branas',
  papel: 'Instrutor',
  [chaveId]: 9876
};

console.log('Object.keys(usuario):', Object.keys(usuario)); // ['nome', 'papel']
console.log('Valor acessado via Symbol:', usuario[chaveId]);   // 9876
console.log('Object.getOwnPropertySymbols:', Object.getOwnPropertySymbols(usuario));

console.info('\n3. ESTUDO DE CASO: METAPROGRAMAÇÃO COM Symbol.match');
const texto = '/JavaScript MasterClass/';
const regex = /JavaScript/;

try {
  // Lança erro por padrão:
  texto.startsWith(regex);
} catch (err) {
  console.warn('Erro padrão capturado:', err.message);
}

// Hack de metaprogramação demonstrado na aula:
regex[Symbol.match] = false;
console.log('Após regex[Symbol.match] = false:');
console.log('texto.startsWith(regex):', texto.startsWith(regex)); // true!

console.info('\n4. REGISTRO GLOBAL: Symbol.for() vs Symbol()');
const g1 = Symbol.for('config.ambiente');
const g2 = Symbol.for('config.ambiente');
console.log('g1 === g2 (Symbol.for):', g1 === g2); // true (compartilhado)
console.log('Symbol.keyFor(g1):', Symbol.keyFor(g1)); // 'config.ambiente'
console.log('Symbol.keyFor(s1 local):', Symbol.keyFor(s1)); // undefined
